#!/usr/bin/env node
/**
 * Compiles CSV data files → ES module Map exports in dist/.
 * Run: node build/compile-lexicon.js
 *
 * Output files (auto-generated — do not edit):
 *   dist/lexicon.js        — 205k-entry word map
 *   dist/abbreviations.js
 *   dist/contractions.js
 *   dist/phrases.js
 */

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { parse } from 'csv-parse/sync';

const ROOT = new URL('..', import.meta.url);
const DATA = new URL('data/', ROOT);
const DIST = new URL('dist/', ROOT);

mkdirSync(fileURLToPath(DIST), { recursive: true });

/**
 * @typedef {{ pos: string[], encoding: number, spellings: string[] }} LexiconEntry
 */

function parseCsv(filename) {
  const raw = readFileSync(new URL(filename, DATA), 'utf8');
  return parse(raw, { columns: true, skip_empty_lines: true, trim: true });
}

function rowToEntry(row) {
  const pos = row.PoS ? row.PoS.split('|').filter(Boolean) : [];
  const encoding = parseInt(row.Encoding, 10);
  const spellings = row.euspelling === '[]' ? [] : row.euspelling.split('|').filter(Boolean);
  return { pos, encoding, spellings };
}

function writeModule(filename, entries) {
  const lines = entries.map(([key, entry]) => {
    const posJson = JSON.stringify(entry.pos);
    const spellingsJson = JSON.stringify(entry.spellings);
    return `  [${JSON.stringify(key)}, { pos: ${posJson}, encoding: ${entry.encoding}, spellings: ${spellingsJson} }]`;
  });
  const content = `// Auto-generated by build/compile-lexicon.js — do not edit\nexport const data = new Map([\n${lines.join(',\n')}\n]);\n`;
  writeFileSync(new URL(filename, DIST), content, 'utf8');
  console.log(`[euspell-build] Wrote dist/${filename} (${entries.length} entries)`);
}

// Lexicon
const lexiconRows = parseCsv('euspell_lexicon.csv');
const lexiconEntries = lexiconRows.map((row) => [row.Word, rowToEntry(row)]);
writeModule('lexicon.js', lexiconEntries);

// Abbreviations
const abbrevRows = parseCsv('euspell_lexicon_abbreviations.csv');
const abbrevEntries = abbrevRows.map((row) => [row.Word ?? row.aka, rowToEntry(row)]);
writeModule('abbreviations.js', abbrevEntries);

// Contractions
const contractionRows = parseCsv('euspell_lexicon_contractions.csv');
const contractionEntries = contractionRows.map((row) => [row.Contraction, rowToEntry(row)]);
writeModule('contractions.js', contractionEntries);

// Phrases
const phraseRows = parseCsv('euspell_lexicon_phrase.csv');
const phraseEntries = phraseRows.map((row) => [row.Phrase, rowToEntry(row)]);
writeModule('phrases.js', phraseEntries);
